(3, 'Invitație la vals', $$Stagiunea Musical Extravaganza: o seară de valsuri și eleganță de epocă, cu Orchestra Filarmonicii Arad.$$, 'CONCERT', 'EXTERNAL', NULL, 'Filarmonica Arad', 2, 'Sala Palatului Cultural', 'Piața George Enescu 1, Arad', 46.1757, 21.3171, '2026-11-15 19:00:00+02', '2026-11-15 21:00:00+02', NULL, 'EXTERNAL', NULL, NULL, NULL, 'https://www.filarmonicaarad.ro/', NULL, 95, 8, 'PUBLISHED', false, 5),
(4, 'SEMPER MOZART – concert vocal-simfonic', $$Dirijor Robert Daniel Rădoiaș. Soliști: Renata Gebe-Fügi (soprană), Antonela Bârnat (mezzosoprană), Nicolae Simonov (tenor), Cristian Hodrea (bas), Kristófi János (orgă). Mozart: Sancta Maria, mater Dei K. 273; Exsultate, jubilate K. 165; Regina coeli K. 276; Veni Sancte Spiritus K. 47; Vesperae solennes de confessore K. 339.$$, 'CONCERT', 'EXTERNAL', NULL, 'Filarmonica Arad', 2, 'Sala Palatului Cultural', 'Piața George Enescu 1, Arad', 46.1757, 21.3171, '2026-11-19 19:00:00+02', '2026-11-19 21:00:00+02', NULL, 'EXTERNAL', NULL, NULL, NULL, 'https://www.filarmonicaarad.ro/', NULL, 140, 15, 'PUBLISHED', false, 5),
(5, 'Poveste în două instrumente', $$Recital cameral: Bach, Vivaldi, Beethoven, Paganini, Kreisler, Liszt, Brahms.$$, 'CONCERT', 'EXTERNAL', NULL, 'Filarmonica Arad', 2, 'Sala Palatului Cultural', 'Piața George Enescu 1, Arad', 46.1757, 21.3171, '2026-11-23 19:00:00+02', '2026-11-23 20:30:00+02', NULL, 'EXTERNAL', NULL, NULL, NULL, 'https://www.filarmonicaarad.ro/', NULL, 60, 4, 'PUBLISHED', false, 5),
